-- Backup generated on 2026-10-25 20:33:37

CREATE OR REPLACE FUNCTION public.fn_get_person_by_user_id(p_tenant_id uuid, p_user_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, user_id uuid, first_name character varying, last_name character varying, relationship character varying, email character varying, mobile_phone character varying, alternate_phone character varying, preferred_contact_method character varying, preferred_language character varying, has_portal_access boolean, receives_daily_updates boolean, receives_photos boolean, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT p.id, p.tenant_id, p.user_id, p.first_name, p.last_name, p.relationship,            p.email, p.mobile_phone, p.alternate_phone, p.preferred_contact_method,            p.preferred_language, p.has_portal_access, p.receives_daily_updates,            p.receives_photos, p.created_at, p.updated_at     FROM persons p     WHERE p.user_id = p_user_id     ORDER BY (p.tenant_id = p_tenant_id) DESC     LIMIT 1; END; $function$ ;
